# ---------------------------------------------------------------- Google Sheets
_book = None
def book():
    global _book
    if _book is None:
        creds = Credentials.from_service_account_file(
            CREDS_FILE, scopes=["https://www.googleapis.com/auth/spreadsheets"])
        b = gspread.authorize(creds).open_by_key(SHEET_ID)
        have = {w.title for w in b.worksheets()}
        for name, h in HEADERS.items():
            if name not in have:
                b.add_worksheet(title=name, rows=1000, cols=12)
            ws = b.worksheet(name)
            if ws.row_values(1) != h:
                ws.update(range_name="A1", values=[h])
        _book = b
    return _book

def rows(name):
    recs = book().worksheet(name).get_all_records(numericise_ignore=["all"])
    for i, r in enumerate(recs, start=2):
        r["_row"] = i
    return recs

def num(x):
    try: return float(x)
    except (TypeError, ValueError): return 0.0

def eq(a, b):
    return hmac.compare_digest(str(a).encode(), str(b).encode())

def delete_rows(idx):
    ws = book().worksheet("Productivity log")
    idx = sorted(idx)
    if idx[-1] - idx[0] + 1 == len(idx):
        ws.delete_rows(idx[0], idx[-1])
    else:
        for r in reversed(idx): ws.delete_rows(r)

def load_subs():
    tph = {r["Process name"]: num(r["Target count / hour"]) for r in rows("Processes")}
    subs = {}
    for r in rows("Productivity log"):
        s = subs.setdefault(r["Submission ID"], dict(
            id=r["Submission ID"], date=r["Date"], band=r["Band"], emp_id=r["Employee ID"],
            emp_name=r["Employee name"], procs=[], notes=[], rows=[]))
        s["rows"].append(r["_row"])
        h = num(r["Hour"])
        if r["Type"] == "Process":
            rate = tph.get(r["Process / Description"], 0)
            c = num(r["Count"]); t = h * rate
            s["procs"].append(dict(name=r["Process / Description"], hour=h, count=c,
                                   desc=str(r.get("Description", "")),
                                   target=round(t, 1), pct=round(c / t * 100) if t else None,
                                   earned=(c / rate) if rate else 0.0))
        else:
            s["notes"].append(dict(desc=r["Process / Description"], hour=h))
    for s in subs.values():
        s["prod"] = sum(p["hour"] for p in s["procs"])
        s["non"] = sum(n["hour"] for n in s["notes"])
        s["total"] = s["prod"] + s["non"]
        s["earned"] = sum(p["earned"] for p in s["procs"])     # hours' worth of standard output
        s["pct"] = round(s["earned"] / DAY_HOURS * 100)         # 8 hrs = 100%
        s["off"] = is_off(s["date"])                            # weekly-off entry: saved, not counted
    return sorted(subs.values(), key=lambda s: s["date"], reverse=True)

def get_sub(sid):
    s = next((s for s in load_subs() if s["id"] == sid), None)
    if not s: abort(404)
    if session["role"] == "employee" and s["emp_id"] != session["emp_id"]: abort(403)
    return s

def parse_form():
    g = request.form.getlist
    procs = [(n, num(h), num(c), d.strip()) for n, h, c, d in zip(g("pn"), g("ph"), g("pc"), g("pd")) if num(h) > 0]
    notes = [(t.strip(), num(h)) for t, h in zip(g("nd"), g("nh")) if num(h) > 0]
    tot = sum(p[1] for p in procs) + sum(n[1] for n in notes)
    err = None
    if not procs and not notes: err = "Add at least one process or note with hours."
    elif tot > DAY_HOURS: err = f"Total {tot:g} hrs is more than {DAY_HOURS} hrs."
    return request.form.get("date") or str(dt.date.today()), procs, notes, err

def write_sub(sid, date, emp, procs, notes):
    now = dt.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    base = [sid, date, *emp]      # emp = (band, id, name)
    out = [base + ["Process", n, h, c, now, d] for n, h, c, d in procs] + \
          [base + ["Note", t, h, "", now, ""] for t, h in notes]
    book().worksheet("Productivity log").append_rows(out, value_input_option="RAW")

# ---------------------------------------------------------------- auth helpers
def need(role=None):
    def deco(f):
        @wraps(f)
        def w(*a, **k):
            r = session.get("role")
            if not r or (role and r != role):
                return redirect("/admin/login" if role == "admin" else "/employee/login")
            return f(*a, **k)
        return w
    return deco

def home():
    return "/admin/log" if session.get("role") == "admin" else "/employee"

