# ---------------------------------------------------------------- routes: common
@app.route("/photo/<role>")
def photo(role):
    import base64
    from flask import Response
    if role not in PHOTOS: abort(404)
    return Response(base64.b64decode(PHOTOS[role].split(",", 1)[1]), mimetype="image/jpeg")

