    sub = dict(date=today, band=session["band"], emp_id=session["emp_id"], emp_name=session["name"],
               procs=[{}], notes=[{}])
    body, ctx = form_page(sub, "/employee/save", "Daily productivity entry")
    all_mine = [s for s in load_subs() if s["emp_id"] == session["emp_id"]]
